import axios from 'axios';
import {
    BASE_CONFIG
} from '@/config/config';

const state = {
    bannerList: [],
    unReadMsgNum: '',
    unReadMsgList: [],
    shopList: [],
    // hotProductList: [],
};

const mutations = {
    initAjax(state) {
        // Fetch banner list
        axios.get(BASE_CONFIG.OSS_SERVICE_ADDRESS + '/djc/statics/homePageBannerConfig/homePageBanner.json')
            .then(response => {
                if (response.status === 200) {
                    let data = response.data;
                    if (typeof data === "string") {
                        state.bannerList = eval("(" + data + ")");
                    } else if (typeof data === "object") {
                        state.bannerList = data;
                    }
                }
            });

        // Fetch error mail suffix list
        axios.get(BASE_CONFIG.OSS_SERVICE_ADDRESS + '/djc/statics/mallCongfig/errorMailSuffix.json')
            .then(response => {
                if (response.status === 200) {
                    let data = response.data,
                        item = [];
                    if (typeof data === "string") {
                        item = eval("(" + data + ")");
                    } else if (typeof data === "object") {
                        item = data;
                    }
                    localStorage.setItem('errorMailSuffix', JSON.stringify(item));
                }
            });

        // The following code is commented out but indicates similar behavior for shopList and hotProductList
        /*
        axios.get(BASE_CONFIG.OSS_SERVICE_ADDRESS + '/djc/statics/homePageShopConfig/homePageShop.json')
            .then(response => {
