                    let data = response.data;
                    if (typeof data === "string") {
                        state.shopList = eval("(" + data + ")");
                    } else if (typeof data === "object") {
                        state.shopList = data;
                    }
                }
            });

        axios.get(BASE_CONFIG.OSS_SERVICE_ADDRESS + '/djc/statics/homePageProductConfig/homePageProduct.json')
            .then(response => {
                if (response.status === 200) {
                    let data = response.data;
                    if (typeof data === "string") {
                        state.hotProductList = eval("(" + data + ")");
                    } else if (typeof data === "object") {
                        state.hotProductList = data;
                    }
                }
            });
        */
    }
};

const actions = {
    initAjax({ commit }) {
        commit('initAjax');
    }
};

export default {
    state,
    mutations,
    actions
};

